update telemetry_parse_rule_config
set is_deleted = 1,
    update_time = current_timestamp
where task_id = #{taskId}
  and is_deleted = 0
  and device_satellite_id in (
      select id
      from device_satellite
      where task_id = #{taskId}
        and type = #{type}
  )
